        errorId: 'q3-error',
        feedbackText: 'Correct answers: SQL, HTML, and CSS.'
      }
    ];

    const getSelectedValues = (name) =>
      Array.from(quizForm.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value);

    const matchesCorrectAnswers = (selected, correct) => {
      if (selected.length !== correct.length) {
        return false;
      }

      return correct.every((value) => selected.includes(value));
    };

    const setGroupError = (question, hasError) => {
      const error = document.getElementById(question.errorId);
      error.hidden = !hasError;
    };

    const setFeedback = (question, message, isCorrect) => {
      const feedback = quizForm.querySelector(`[data-feedback-for="${question.name}"]`);
      feedback.hidden = false;
      feedback.textContent = message;
      feedback.classList.toggle('is-correct', isCorrect);
      feedback.classList.toggle('is-incorrect', !isCorrect);
    };

    questions.forEach((question) => {
      quizForm.querySelectorAll(`input[name="${question.name}"]`).forEach((input) => {
        input.addEventListener('change', () => {
          if (getSelectedValues(question.name).length > 0) {
            setGroupError(question, false);
          }
        });
      });
    });

    quizForm.addEventListener('submit', (event) => {
      event.preventDefault();

      let firstInvalidInput = null;
      let score = 0;

      questions.forEach((question) => {
        const inputs = quizForm.querySelectorAll(`input[name="${question.name}"]`);
        const selected = getSelectedValues(question.name);
        const hasSelection = selected.length > 0;

        setGroupError(question, !hasSelection);

        if (!hasSelection && !firstInvalidInput) {
          firstInvalidInput = inputs[0];
        }

        if (hasSelection) {
          const isCorrect = matchesCorrectAnswers(selected, question.correct);

          if (isCorrect) {
            score += 1;
            setFeedback(question, 'Correct.', true);
          } else {
            setFeedback(question, `Not quite. ${question.feedbackText}`, false);
          }
        } else {
          setFeedback(question, 'Please answer this question before submitting.', false);
        }
      });

      if (firstInvalidInput) {
        result.textContent = 'Please answer every question before viewing your score.';
        firstInvalidInput.focus();
        return;
      }

      result.textContent = `You scored ${score} out of ${questions.length}.`;
      result.tabIndex = -1;
      result.focus();
    });
