         <div class="form-field">
           <fieldset aria-describedby="q1-help q1-error">
             <legend>1. Which of these are programming languages often used in web development? <span class="required-marker" aria-hidden="true">*</span></legend>
             <p id="q1-help" class="question-help">Select every option that is a programming language, not a stylesheet or markup language.</p>
             <div class="choices">
               <label class="choice" for="q1-javascript">
                 <input id="q1-javascript" type="checkbox" name="q1" value="JavaScript">
                 <span>JavaScript</span>
               </label>
               <label class="choice" for="q1-python">
                 <input id="q1-python" type="checkbox" name="q1" value="Python">
                 <span>Python</span>
               </label>
               <label class="choice" for="q1-html">
                 <input id="q1-html" type="checkbox" name="q1" value="HTML">
                 <span>HTML</span>
               </label>
               <label class="choice" for="q1-css">
                 <input id="q1-css" type="checkbox" name="q1" value="CSS">
                 <span>CSS</span>
               </label>
             </div>
             <p id="q1-error" class="error-text" hidden>Error: Select at least one answer for question 1.</p>
           </fieldset>
           <p class="feedback" data-feedback-for="q1" hidden></p>
         </div>

         <div class="form-field">
           <fieldset aria-describedby="q2-error">
             <legend>2. Which of these languages are commonly compiled before they run? <span class="required-marker" aria-hidden="true">*</span></legend>
             <div class="choices">
               <label class="choice" for="q2-c">
                 <input id="q2-c" type="checkbox" name="q2" value="C">
                 <span>C</span>
               </label>
               <label class="choice" for="q2-cpp">
                 <input id="q2-cpp" type="checkbox" name="q2" value="C++">
                 <span>C++</span>
               </label>
               <label class="choice" for="q2-rust">
                 <input id="q2-rust" type="checkbox" name="q2" value="Rust">
                 <span>Rust</span>
               </label>
               <label class="choice" for="q2-ruby">
                 <input id="q2-ruby" type="checkbox" name="q2" value="Ruby">
                 <span>Ruby</span>
               </label>
             </div>
             <p id="q2-error" class="error-text" hidden>Error: Select at least one answer for question 2.</p>
           </fieldset>
           <p class="feedback" data-feedback-for="q2" hidden></p>
         </div>

         <div class="form-field">
           <fieldset aria-describedby="q3-error">
             <legend>3. Which of these are not general-purpose programming languages? <span class="required-marker" aria-hidden="true">*</span></legend>
             <div class="choices">
               <label class="choice" for="q3-sql">
                 <input id="q3-sql" type="checkbox" name="q3" value="SQL">
                 <span>SQL</span>
               </label>
               <label class="choice" for="q3-html">
                 <input id="q3-html" type="checkbox" name="q3" value="HTML">
                 <span>HTML</span>
               </label>
               <label class="choice" for="q3-java">
                 <input id="q3-java" type="checkbox" name="q3" value="Java">
                 <span>Java</span>
               </label>
               <label class="choice" for="q3-css">
                 <input id="q3-css" type="checkbox" name="q3" value="CSS">
                 <span>CSS</span>
               </label>
             </div>
             <p id="q3-error" class="error-text" hidden>Error: Select at least one answer for question 3.</p>
           </fieldset>
           <p class="feedback" data-feedback-for="q3" hidden></p>
         </div>

         <div class="actions">
           <button type="submit">Submit quiz</button>
           <div id="result" class="result" role="status"></div>
         </div>
         <p class="result-note">A question counts as correct when the full set of correct answers is selected.</p>
       </form>
     </section>
   </main>

   <script>
     const quizForm = document.getElementById('quiz-form');
     const result = document.getElementById('result');

     const questions = [
       {
         name: 'q1',
         correct: ['JavaScript', 'Python'],
         errorId: 'q1-error',
         feedbackText: 'Correct answers: JavaScript and Python.'
       },
       {
         name: 'q2',
         correct: ['C', 'C++', 'Rust'],
         errorId: 'q2-error',
         feedbackText: 'Correct answers: C, C++, and Rust.'
       },
       {
         name: 'q3',
         correct: ['SQL', 'HTML', 'CSS'],
         errorId: 'q3-error',
         feedbackText: 'Correct answers: SQL, HTML, and CSS.'
       }
     ];

     const getSelectedValues = (name) =>
       Array.from(quizForm.querySelectorAll(`input[name="${name}"]:checked`)).map((input) => input.value);

     const matchesCorrectAnswers = (selected, correct) => {
       if (selected.length !== correct.length) {
         return false;
       }

       return correct.every((value) => selected.includes(value));
     };

     const setGroupError = (question, hasError) => {
       const error = document.getElementById(question.errorId);
       error.hidden = !hasError;
     };

     const setFeedback = (question, message, isCorrect) => {
       const feedback = quizForm.querySelector(`[data-feedback-for="${question.name}"]`);
       feedback.hidden = false;
       feedback.textContent = message;
       feedback.classList.toggle('is-correct', isCorrect);
       feedback.classList.toggle('is-incorrect', !isCorrect);
     };

     questions.forEach((question) => {
       quizForm.querySelectorAll(`input[name="${question.name}"]`).forEach((input) => {
         input.addEventListener('change', () => {
           if (getSelectedValues(question.name).length > 0) {
             setGroupError(question, false);
           }
         });
       });
     });

     quizForm.addEventListener('submit', (event) => {
       event.preventDefault();

       let firstInvalidInput = null;
       let score = 0;

       questions.forEach((question) => {
         const inputs = quizForm.querySelectorAll(`input[name="${question.name}"]`);
         const selected = getSelectedValues(question.name);
         const hasSelection = selected.length > 0;

         setGroupError(question, !hasSelection);

         if (!hasSelection && !firstInvalidInput) {
           firstInvalidInput = inputs[0];
         }

         if (hasSelection) {
           const isCorrect = matchesCorrectAnswers(selected, question.correct);

           if (isCorrect) {
             score += 1;
             setFeedback(question, 'Correct.', true);
           } else {
             setFeedback(question, `Not quite. ${question.feedbackText}`, false);
           }
         } else {
           setFeedback(question, 'Please answer this question before submitting.', false);
         }
       });

       if (firstInvalidInput) {
         result.textContent = '';
         firstInvalidInput.focus();
         return;
       }

       result.textContent = `You scored ${score} out of ${questions.length}.`;
     });
   </script>
